config->parser = (struct parser) {
        .state = parse_config,
        .lexer = {
            .state = lex_config,
            .pos = data,
            .start = data,
            .end = (char *)data + len,
            .cur_line = 1,
        }
    };

config->parser = (struct parser) {
        .state = parse_config,
        .lexer = {
            .state = lex_config,
            .pos = data,
            .start = data,
            .end = (char *)data + len,
            .cur_line = 1,
        }
    };

do {
        chr = next(lexer);

        if (chr == '$' && peek(lexer) == '{') {
            backup(lexer);
            emit(lexer, LEXEME_STRING);

            advance_n(lexer, strlen("{"));

            return lex_variable;
        }
    } while (isstring(chr));

